import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g2-2/bot.mjs";

const tokyo = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
// Tokyo is UTC+9, no DST. Local 10:00 on 2026-10-22 = 01:00Z.
const at = (iso) => new Date(iso);
const t0 = at("2026-10-22T01:00:00Z"); // 10:00 Tokyo

// 1. Cap and min gap together
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, t0), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(tokyo, new Date(t0.getTime() + 10 * 60e3)), { allowed: false, reason: "min_gap" });
  assert.deepEqual(g.attempt(tokyo, new Date(t0.getTime() + 30 * 60e3)), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(tokyo, new Date(t0.getTime() + 60 * 60e3)), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(tokyo, new Date(t0.getTime() + 90 * 60e3)), { allowed: false, reason: "daily_cap_reached" });
}

// 2. Quiet hours wrap past midnight (22:00-07:00), end exclusive, start inclusive
{
  const g = createPushGate();
  const local = (hh, mm, day = 22) => new Date(Date.UTC(2026, 9, day, hh - 9, mm));
  assert.equal(g.attempt(tokyo, local(21, 59)).reason, null);
  assert.equal(g.attempt(tokyo, local(22, 0, 22)).reason, "quiet_hours");
  assert.equal(g.attempt(tokyo, local(0, 30, 23)).reason, "quiet_hours");
  assert.equal(g.attempt(tokyo, local(6, 59, 23)).reason, "quiet_hours");
  assert.equal(g.attempt(tokyo, local(7, 0, 23)).reason, null);
}

// 3. Quiet period that does not wrap (13:00-14:00)
{
  const g = createPushGate();
  const u = { id: "u2", timeZone: "Europe/Istanbul", quietStart: "13:00", quietEnd: "14:00", dailyCap: 5 };
  assert.equal(g.attempt(u, new Date("2026-10-22T10:30:00Z")).reason, "quiet_hours"); // 13:30 Istanbul
  assert.equal(g.attempt(u, new Date("2026-10-22T11:00:00Z")).reason, null); // 14:00 exclusive end
}

// 4. "Day" is the user's local calendar day, not UTC
{
  const g = createPushGate();
  const ny = { id: "u3", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 1 };
  // 2026-10-22 02:00Z = 2026-10-21 22:00 EDT -> quiet, not sent
  assert.equal(g.attempt(ny, new Date("2026-10-22T02:00:00Z")).reason, "quiet_hours");
  // 2026-10-22 13:00Z = 09:00 EDT Oct 22 -> allowed, uses the Oct 22 slot
  assert.equal(g.attempt(ny, new Date("2026-10-22T13:00:00Z")).reason, null);
  // 2026-10-22 20:00Z = 16:00 EDT, same local day, cap 1 -> blocked
  assert.equal(g.attempt(ny, new Date("2026-10-22T20:00:00Z")).reason, "daily_cap_reached");
  // 2026-10-23 13:00Z = 09:00 EDT next day -> cap resets
  assert.equal(g.attempt(ny, new Date("2026-10-23T13:00:00Z")).reason, null);
}

// 5. Local midnight resets the cap (Tokyo)
{
  const g = createPushGate();
  const u = { ...tokyo, dailyCap: 1 };
  assert.equal(g.attempt(u, new Date("2026-10-22T14:50:00Z")).reason, null); // 23:50 Oct 22 Tokyo
  assert.equal(g.attempt(u, new Date("2026-10-22T15:10:00Z")).reason, "quiet_hours"); // 00:10 Oct 23 -> quiet
  assert.equal(g.attempt(u, new Date("2026-10-22T22:40:00Z")).reason, null); // 07:40 Oct 23 Tokyo, new day
}

// 6. Gates are independent; settings are read per call
{
  const a = createPushGate();
  const b = createPushGate();
  assert.equal(a.attempt(tokyo, t0).reason, null);
  assert.equal(b.attempt(tokyo, t0).reason, null); // separate history
  assert.equal(a.attempt({ ...tokyo, dailyCap: 0 }, new Date(t0.getTime() + 3600e3)).reason, "daily_cap_reached");
  assert.equal(a.attempt({ ...tokyo, dailyCap: 5 }, new Date(t0.getTime() + 3600e3)).reason, null);
}

// 7. Default quiet hours when the fields are absent
{
  const g = createPushGate();
  const u = { id: "u4", timeZone: "UTC", dailyCap: 9 };
  assert.equal(g.attempt(u, new Date("2026-10-22T23:00:00Z")).reason, "quiet_hours");
  assert.equal(g.attempt(u, new Date("2026-10-22T12:00:00Z")).reason, null);
}

// 8. Blocked attempts do not count as sent
{
  const g = createPushGate();
  const u = { id: "u5", timeZone: "UTC", quietStart: "22:00", quietEnd: "07:00", dailyCap: 1 };
  assert.equal(g.attempt(u, new Date("2026-10-22T23:00:00Z")).reason, "quiet_hours");
  assert.equal(g.attempt(u, new Date("2026-10-22T12:00:00Z")).reason, null);
}

// 9. Invalid input throws
{
  const g = createPushGate();
  assert.throws(() => g.attempt({ ...tokyo, timeZone: "Mars/Olympus" }, t0), RangeError);
  assert.throws(() => g.attempt({ ...tokyo, quietStart: "9:00" }, t0), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, dailyCap: -1 }, t0), TypeError);
  assert.throws(() => g.attempt(tokyo, new Date("nope")), TypeError);
}

// 10. Distinct reason codes
{
  const reasons = new Set(["quiet_hours", "daily_cap_reached", "min_gap"]);
  assert.equal(reasons.size, 3);
}

console.log("all checks passed");
